        if (allPortlets != null) {
            for (Portlet portlet : allPortlets) {
                if (portlet.getPortletName().equals(PRESENTATORE_FORMS_PORTLET_ID)) {
                    instancePortleId = portlet.getPortletId();
                    break;
                }
            }
