    private Layout getLayoutFromDomandaBando(DomandaBando domandaBando) throws PortalException {

        Bando bando = bandoLocalService.getBando(domandaBando.getBandoId());

        long layoutId = 0;

        if (Validator.isNotNull(bando.getLayoutId())) {
            layoutId = bando.getLayoutId();
        }

        Layout layout = layoutLocalService.getLayout(domandaBando.getGroupId(), false, layoutId);
        return layout;
    }

