private MessaggioDTO mapMessaggio(Messaggio messaggio) {
    MessaggioDTO messaggioDto = null;

    if (Validator.isNotNull(messaggio)) {
        messaggioDto = new MessaggioDTO();
        messaggioDto.setContenuto(messaggio.getContenuto());
        messaggioDto.setCreateDate(messaggio.getCreateDate());
    }

    return messaggioDto;
}

private ComunicazioneDto mapComunicazioni(Comunicazione comunicazione) {

    ComunicazioneDto comunicazioneDto = null;

    if (Validator.isNotNull(comunicazione)) {
        comunicazioneDto = new ComunicazioneDto();
        comunicazioneDto.setCreateDate(comunicazione.getCreateDate());
        comunicazioneDto.setId(comunicazione.getComunicazioneId());
        comunicazioneDto.setDataInvio(comunicazione.getDataInvio());

        if (Validator.isNotNull(comunicazione.getUriServizio())) {
            comunicazioneDto.setUriServizio(comunicazione.getUriServizio());
        }

        if (comunicazione.getDomandaBandoId() > 0) {
            comunicazioneDto.setDomandaBandoId(comunicazione.getDomandaBandoId());
        }

        if (comunicazione.getRichiestaId() > 0) {
            comunicazioneDto.setRichiestaId(comunicazione.getRichiestaId());
        }

        List<Messaggio> listaMessaggi = messaggioLocalService.getMessaggi(comunicazione.getComunicazioneId(), QueryUtil.ALL_POS, QueryUtil.ALL_POS);
        if (listaMessaggi != null && !listaMessaggi.isEmpty()) {

            Comparator<Date> dateComparator = (o1, o2) -> o1.compareTo(o2);
            Date dataUltimoMessaggio = listaMessaggi.stream().map(messaggio -> messaggio.getCreateDate()).collect(Collectors.maxBy(dateComparator)).get();

            comunicazioneDto.setDataUltimoMessaggio(dataUltimoMessaggio);

            List<MessaggioDTO> listaMessaggiDto = listaMessaggi.stream().map(this::mapMessaggio).collect(Collectors.toList());

            if (listaMessaggiDto != null && !listaMessaggiDto.isEmpty()) {
                comunicazioneDto.setMessaggi(listaMessaggiDto);
                comunicazioneDto.setNumMess(listaMessaggiDto.size());
            }
        }

        comunicazioneDto.setTipologia(TipologiaComunicazione.COMUNICAZIONE.name());
        comunicazioneDto.setTitolo(comunicazione.getTitolo());

        comunicazioneDto.setLetta(comunicazione.isLetta());
    }

    return comunicazioneDto;

}

private List<ComunicazioneDto> getListaCommentiMergeRichiesteDomandeBando(String codiceFiscale, Locale locale, long companyId) {
    List<ComunicazioneDto> listaComunicazioni = new ArrayList<ComunicazioneDto>();
    MessageUtility messageUtility = new MessageUtility(ScrivaniaCittadinoPortletKeys.BUNDLE_SYMBOLIC_NAME, locale);
    if (!Validator.isBlank(codiceFiscale)) {
        List<CommentoDomandaBando> listaCommentiDomandaBando = commentoDomandaBandoLocalService.findCommentiByCodiceFiscaleAndVisibileAndCompanyId(codiceFiscale, companyId);
        List<ComunicazioneDto> listaCommentiDomandaBandoDTO = new ArrayList<ComunicazioneDto>();

        List<CommentoRichiesta> listaCommentiRichiesta = commentoRichiestaLocalService.getCommentiByCodiceFiscaleAndVisibileAndCompanyId(codiceFiscale, companyId);
        List<ComunicazioneDto> listaCommentiRichiestaDTO = new ArrayList<ComunicazioneDto>();
        if (listaCommentiDomandaBando != null && !listaCommentiDomandaBando.isEmpty()) {
            Stream<ComunicazioneDto> commentiDomandaBando = listaCommentiDomandaBando.stream().map(this::mapCommentiDomandeBando).map(el -> {
                el.setTitolo(messageUtility.getMessage("titolo-comunicazione-domanda-bando", String.valueOf(el.getDomandaBandoId())));
                return el;
            });

            listaCommentiDomandaBandoDTO = commentiDomandaBando.collect(Collectors.toList());

            if (listaCommentiDomandaBandoDTO != null && !listaCommentiDomandaBandoDTO.isEmpty()) {
                listaComunicazioni.addAll(listaCommentiDomandaBandoDTO);
            }
        }

        if (listaCommentiRichiesta != null && !listaCommentiRichiesta.isEmpty()) {
            Stream<ComunicazioneDto> commentiRichiesta = listaCommentiRichiesta.stream().map(this::mapCommentiRichiesta).map(el -> {
                el.setTitolo(messageUtility.getMessage("titolo-comunicazione-richiesta-servizio", String.valueOf(el.getRichiestaId())));
                return el;
            });
