            // }
            listaCommentiRichiestaDTO = commentiRichiesta.collect(Collectors.toList());

            if (listaCommentiRichiestaDTO != null && !listaCommentiRichiesta.isEmpty()) {
                listaComunicazioni.addAll(listaCommentiRichiestaDTO);
            }
        }
    }

    return listaComunicazioni;
}

